INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_borrowed_idiom$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "idiome", "vector": "language"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe ein Idiom über den Drift getragen, das sich nicht übersetzen lässt. Unterwegs ertappte ich mich, wie ich in einer Sprache dachte, die ich nie gelernt habe.", "text_en": "I carried an idiom across the Drift that cannot be translated. On the way I caught myself thinking in a language I never learned."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Ein Satz, den niemand hier sprechen kann, hängt einen Moment in der Luft.", "text_en": "A fading echo brushes {sim}. A sentence no one here can speak hangs in the air for a moment.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger sprach {agent} ein Idiom aus einer anderen Welt vor. {agent} versteht es nicht, und kann es trotzdem nicht mehr vergessen.", "text_en": "A courier spoke {agent} an idiom from another world. {agent} does not understand it, and still cannot forget it."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist eine Redewendung aus dem Drift angekommen. Sie hat hier noch keine Bedeutung, aber die Münder formen sie schon.", "text_en": "A turn of phrase from the Drift has reached {sim}. It has no meaning here yet, but the mouths are already shaping it.", "title_de": "Drift-Depesche · Geliehenes Idiom", "title_en": "Drift Dispatch · Borrowed Idiom"}], "prose": {"brief_de": "Eine Redewendung, für die es hier kein Wort gibt, will in eine Welt getragen werden, die sie noch nicht kennt.", "brief_en": "A turn of phrase with no word for it here wants carrying to a world that does not yet know it.", "title_de": "Depesche · Geliehenes Idiom", "title_en": "Dispatch · Borrowed Idiom"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_dream_cargo$DQ$, $DQ$deliver$DQ$, 2, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "traumfracht", "vector": "dream"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe Traumfracht über den Drift getragen. Sie wollte ständig woanders sein als in meinen Händen, und einmal träumte ich ihren Inhalt, statt ihn zu tragen.", "text_en": "I carried dream-freight across the Drift. It kept wanting to be anywhere but in my hands, and once I dreamed its contents instead of carrying them."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Für einen Lidschlag träumt die Stadt etwas, das ihr nicht gehört.", "text_en": "A fading echo brushes {sim}. For the space of a blink the city dreams something that is not its own.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger überließ {agent} eine Traumfracht aus einer anderen Welt. {agent} wird heute Nacht etwas träumen, das jemand anderes erfunden hat.", "text_en": "A courier left {agent} a dream-freight from another world. Tonight {agent} will dream something that someone else invented."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist Traumfracht aus dem Drift eingetroffen. Am Rand des Schlafs sickert etwas Fremdes in die Welt.", "text_en": "Dream-freight from the Drift has arrived in {sim}. At the edge of sleep something foreign seeps into the world.", "title_de": "Drift-Depesche · Traumfracht", "title_en": "Drift Dispatch · Dream-Freight"}], "prose": {"brief_de": "Flüchtige Traumfracht, luzide und ungeduldig. Sie muss ankommen, bevor sie sich beim Wachwerden auflöst.", "brief_en": "Volatile dream-freight, lucid and impatient. It must arrive before waking dissolves it.", "title_de": "Depesche · Traumfracht", "title_en": "Dispatch · Dream-Freight"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_memory_parcel$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "erinnerungsstuecke", "vector": "memory"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe ein Erinnerungsstück über den Drift getragen. An der Schwelle wurde es kurz schwer, als wöge die fremde Erinnerung mehr als die eigene.", "text_en": "I carried a memory-relic across the Drift. At the threshold it grew briefly heavy, as if the borrowed memory weighed more than my own."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Irgendwo in der Nähe hat eine Erinnerung, die nicht hierher gehört, die Schwelle berührt.", "text_en": "A fading echo brushes {sim}. Somewhere close, a memory that does not belong here has touched the threshold.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger brachte {agent} ein Erinnerungsstück aus einer anderen Welt. Es zeigt einen Ort, den es hier nie gegeben hat, und doch kommt er bekannt vor.", "text_en": "A courier brought {agent} a memory-relic from another world. It shows a place that never existed here, and yet it feels familiar."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} ist ein Erinnerungsstück aus dem Drift eingetroffen. Wer es ansieht, erinnert sich an Dinge, die nie geschehen sind.", "text_en": "A memory-relic from the Drift has arrived in {sim}. Those who look at it remember things that never happened.", "title_de": "Drift-Depesche · Erinnerungsstück", "title_en": "Drift Dispatch · Memory-Relic"}], "prose": {"brief_de": "Ein Erinnerungsstück will über den Drift getragen werden, ein Gegenstand, der sich an einen anderen Ort erinnert.", "brief_en": "A memory-relic asks to be carried across the Drift, an object that remembers somewhere else.", "title_de": "Depesche · Erinnerungsstück", "title_en": "Dispatch · Memory-Relic"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;
INSERT INTO travel_quest_templates (template_key, family, tier, pack_slug, definition) VALUES ($DQ$deliver_sealed_contract$DQ$, $DQ$deliver$DQ$, 1, $DQ$drift_p0c_seed$DQ$, $JB${"cargo": {"family": "kontrakte", "vector": "commerce"}, "effects": [{"kind": "emit_fragment", "text_de": "Ich habe einen versiegelten Kontrakt über den Drift getragen. Solange das Wachs hielt, fühlte sich die Reise an wie eine Schuld, die ich noch nicht kannte.", "text_en": "I carried a sealed contract across the Drift. As long as the wax held, the journey felt like a debt I did not yet know I owed."}, {"kind": "emit_echo", "text_de": "Ein verklingendes Echo streift {sim}. Eine Unterschrift, die niemand hier geleistet hat, beginnt zu binden.", "text_en": "A fading echo brushes {sim}. A signature no one here ever made begins to bind.", "title_de": "Echo aus dem Drift", "title_en": "Echo from the Drift"}, {"importance": 4, "kind": "inject_agent_memory", "text_de": "Ein Träger legte {agent} einen versiegelten Kontrakt aus einer anderen Welt vor. Die Klauseln sind in einer Hand geschrieben, die {agent} zu kennen glaubt.", "text_en": "A courier presented {agent} a sealed contract from another world. Its clauses are written in a hand {agent} believes they recognise."}, {"impact_level": 3, "kind": "spawn_event", "text_de": "In {sim} wurde ein Kontrakt aus dem Drift eingelöst. Eine Abmachung gilt nun, die diese Welt nie geschlossen hat.", "text_en": "A contract from the Drift has been honored in {sim}. An agreement now holds that this world never made.", "title_de": "Drift-Depesche · Versiegelter Kontrakt", "title_en": "Drift Dispatch · Sealed Contract"}], "prose": {"brief_de": "Ein versiegelter Kontrakt sucht den Ort, an dem er eingelöst werden muss. Das Siegel darf erst am Ziel brechen.", "brief_en": "A sealed contract seeks the place where it must be honored. The seal may break only at its destination.", "title_de": "Depesche · Versiegelter Kontrakt", "title_en": "Dispatch · Sealed Contract"}}$JB$::jsonb) ON CONFLICT (template_key) DO UPDATE SET family = EXCLUDED.family, tier = EXCLUDED.tier, pack_slug = EXCLUDED.pack_slug, definition = EXCLUDED.definition;

COMMIT;
